// The Chebyshev fallback against the Rust server's own numbers: the same
// direct-formula fixtures as the STAB test, but read through the coefficient
// file. This proves the fallback — the file the app ships for when the
// server is slow or unreachable — reproduces the panchanga, not just the
// positions. Fixture generated by `siddhanta-table cheb-build` from the
// 2000 table (see apps/rust/crates/siddhanta-table/README.md).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import {
  chebPositionsAt,
  parseChebTable,
} from "../src/astronomy/chebyshev";
import {
  displaySpeedAt,
  grahaAt,
  karanaAt,
  lagnaAt,
  nextNakshatraBoundary,
  nextTithiBoundary,
  sunriseSunset,
  tithiAt,
  yogaAt,
} from "../src/astronomy/siddhanta-offline";
import { chebSource, loadSiddhantaSource } from "../src/astronomy/siddhanta-source";

const KATHMANDU_LAT = 27.7172;
const KATHMANDU_LON = 85.324;

interface Fixture {
  jd: number;
  longitude: number[];
  speed: number[];
  ayanamsha: number;
  mean_sun_sayana: number;
  tithi: number;
  tithi_progress: number;
  nakshatra: number;
  pada: number;
  nakshatra_progress: number;
  yoga: number;
  yoga_progress: number;
  karana: number;
  karana_progress: number;
  moon_rashi: number;
  sun_rashi: number;
  lagna: number;
}

interface SunFixture {
  start_jd: number;
  sunrise_jd: number;
  sunset_jd: number;
}

function loadFixtures(): {
  table: ReturnType<typeof parseChebTable>;
  rows: Fixture[];
  sun: SunFixture[];
} {
  // The table is stored base64 (the snapshot push cannot carry binary
  // files); decoding it gives back the exact CHEB bytes.
  const tableB64 = readFileSync(
    new URL("./fixtures/chebyshev-2000.cheb.b64", import.meta.url),
    "utf8",
  );
  const table = parseChebTable(new Uint8Array(Buffer.from(tableB64.trim(), "base64")));
  const rows = JSON.parse(
    readFileSync(new URL("./fixtures/siddhanta-2000.json", import.meta.url), "utf8"),
  ) as Fixture[];
  const sun = JSON.parse(
    readFileSync(new URL("./fixtures/siddhanta-2000-sun.json", import.meta.url), "utf8"),
  ) as SunFixture[];
  return { table, rows, sun };
}

function angleClose(actual: number, expected: number, toleranceDegrees: number): void {
  let diff = ((actual - expected) % 360 + 540) % 360 - 180;
  diff = Math.abs(diff);
  assert.ok(diff <= toleranceDegrees, `expected ${actual} within ${toleranceDegrees}° of ${expected}`);
}

test("chebyshev longitudes match the server's direct formulas", () => {
  const { table, rows } = loadFixtures();
  // Same tolerances as the STAB test: the Moon's fit leaves up to ~9" over
  // the whole 200-year file, the rest under ~1.5".
  const tolerance = [0.001, 0.003, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001];
  for (const row of rows) {
    const positions = chebPositionsAt(table, row.jd);
    assert.ok(positions !== null, `JD ${row.jd} is inside the table`);
    for (let b = 0; b < 8; b += 1) {
      angleClose(positions.longitude[b], row.longitude[b], tolerance[b]);
    }
    assert.ok(Math.abs(positions.ayanamsha - row.ayanamsha) < 0.001, `ayanamsha JD ${row.jd}`);
    assert.ok(
      Math.abs(positions.meanSunSayana - row.mean_sun_sayana) < 0.001,
      `mean Sun JD ${row.jd}`,
    );
  }
});

test("display speeds, tithi, nakshatra, yoga and karana match the server", () => {
  const { table, rows } = loadFixtures();
  const source = chebSource(table);
  const bodies = ["sun", "moon", "mars", "mercury", "jupiter", "venus", "saturn", "rahu"] as const;
  for (const row of rows) {
    for (let b = 0; b < 8; b += 1) {
      const speed = displaySpeedAt(source, row.jd, bodies[b]);
      assert.ok(speed !== null, `JD ${row.jd} ${bodies[b]} is inside the table`);
      assert.ok(
        Math.abs(speed - row.speed[b]) < 0.005,
        `JD ${row.jd} ${bodies[b]}: ${speed} vs ${row.speed[b]}`,
      );
    }
    const positions = chebPositionsAt(table, row.jd);
    assert.ok(positions !== null);
    const sun = positions.longitude[0];
    const moon = positions.longitude[1];
    const tithi = tithiAt(sun, moon);
    assert.equal(tithi.number, row.tithi, `tithi JD ${row.jd}`);
    assert.ok(Math.abs(tithi.progress - row.tithi_progress) < 0.002, `tithi progress JD ${row.jd}`);
    const graha = grahaAt(moon);
    assert.equal(graha.nakshatra, row.nakshatra, `nakshatra JD ${row.jd}`);
    assert.equal(graha.pada, row.pada, `pada JD ${row.jd}`);
    assert.ok(
      Math.abs(graha.nakshatraProgress - row.nakshatra_progress) < 0.002,
      `nakshatra progress JD ${row.jd}`,
    );
    assert.equal(graha.rashi, row.moon_rashi, `Moon rashi JD ${row.jd}`);
    assert.equal(grahaAt(sun).rashi, row.sun_rashi, `Sun rashi JD ${row.jd}`);
    const yoga = yogaAt(sun, moon);
    assert.equal(yoga.number, row.yoga, `yoga JD ${row.jd}`);
    assert.ok(Math.abs(yoga.progress - row.yoga_progress) < 0.002, `yoga progress JD ${row.jd}`);
    const karana = karanaAt(sun, moon);
    assert.equal(karana.number, row.karana, `karana JD ${row.jd}`);
    assert.ok(Math.abs(karana.progress - row.karana_progress) < 0.002, `karana progress JD ${row.jd}`);
  }
});

test("lagna, sunrise and sunset match the server for Kathmandu", () => {
  const { table, rows, sun } = loadFixtures();
  const source = chebSource(table);
  for (const row of rows) {
    const lagna = lagnaAt(source, row.jd, KATHMANDU_LAT, KATHMANDU_LON);
    assert.ok(lagna !== null);
    angleClose(lagna, row.lagna, 0.02);
  }
  for (const day of sun) {
    const found = sunriseSunset(source, day.start_jd, KATHMANDU_LAT, KATHMANDU_LON);
    assert.ok(found.sunriseJd !== null, `sunrise ${day.start_jd}`);
    assert.ok(found.sunsetJd !== null, `sunset ${day.start_jd}`);
    assert.ok(
      Math.abs(found.sunriseJd - day.sunrise_jd) < 0.0014,
      `sunrise ${day.start_jd}: ${found.sunriseJd} vs ${day.sunrise_jd}`,
    );
    assert.ok(
      Math.abs(found.sunsetJd - day.sunset_jd) < 0.0014,
      `sunset ${day.start_jd}: ${found.sunsetJd} vs ${day.sunset_jd}`,
    );
  }
});

test("next tithi and nakshatra boundaries land on a real change", () => {
  const { table, rows } = loadFixtures();
  const source = chebSource(table);
  const row = rows[0];
  const positions = chebPositionsAt(table, row.jd);
  assert.ok(positions !== null);
  const tithiBoundary = nextTithiBoundary(source, row.jd);
  assert.ok(tithiBoundary !== null && tithiBoundary > row.jd);
  const before = chebPositionsAt(table, tithiBoundary - 1 / 1440);
  const after = chebPositionsAt(table, tithiBoundary + 1 / 1440);
  assert.ok(before !== null && after !== null);
  assert.notEqual(
    tithiAt(before.longitude[0], before.longitude[1]).number,
    tithiAt(after.longitude[0], after.longitude[1]).number,
  );
  const nakshatraBoundary = nextNakshatraBoundary(source, row.jd);
  assert.ok(nakshatraBoundary !== null && nakshatraBoundary > row.jd);
  const nBefore = chebPositionsAt(table, nakshatraBoundary - 1 / 1440);
  const nAfter = chebPositionsAt(table, nakshatraBoundary + 1 / 1440);
  assert.ok(nBefore !== null && nAfter !== null);
  assert.notEqual(
    grahaAt(nBefore.longitude[1]).nakshatra,
    grahaAt(nAfter.longitude[1]).nakshatra,
  );
});

test("a bad magic and a truncated file are rejected", () => {
  const wrongMagic = new Uint8Array(56);
  wrongMagic.set([67, 72, 69, 66, 88, 48, 48, 48]); // "CHEBX000"
  assert.throws(() => parseChebTable(wrongMagic), /bad magic/);
  assert.throws(() => parseChebTable(new Uint8Array(40)), /too short/);
  // A header that promises one segment but brings fewer bytes than it needs.
  const short = new Uint8Array(60);
  short.set([67, 72, 69, 66, 48, 48, 48, 49]); // "CHEB0001"
  const view = new DataView(short.buffer);
  view.setUint32(8, 8, true); // bodies
  view.setUint32(12, 1, true); // one segment
  view.setFloat64(24, 32, true); // segment days
  view.setFloat64(40, 0.9856, true); // mean Sun rate
  short[48] = 4; // Sun degree 4, the rest 0: a segment is 48 bytes, not 4
  assert.throws(() => parseChebTable(short), /segment count/);
});

test("the loader uses the server when it answers, and the bundled file when it does not", async () => {
  const { table } = loadFixtures();
  const bundledBytes = readFileSync(
    new URL("./fixtures/chebyshev-2000.cheb.b64", import.meta.url),
    "utf8",
  );
  const bundled = () =>
    Promise.resolve(new Uint8Array(Buffer.from(bundledBytes.trim(), "base64")));
  const jd = 2451545.0; // 1 Jan 2000, inside the fixture

  // A failing fetch falls back to the bundled file.
  const failed = await loadSiddhantaSource(jd, {
    baseUrl: "https://example.invalid",
    bundledCheb: bundled,
    fetchImpl: async () => {
      throw new Error("unreachable");
    },
  });
  assert.equal(failed.via, "bundled");
  const fallback = failed.source.positionsAt(jd);
  assert.ok(fallback !== null);
  angleClose(fallback.longitude[1], chebPositionsAt(table, jd)?.longitude[1] ?? -1, 0.0001);

  // A slow fetch (past the timeout) falls back the same way.
  const slow = await loadSiddhantaSource(jd, {
    baseUrl: "https://example.invalid",
    timeoutMs: 10,
    bundledCheb: bundled,
    fetchImpl: async (_url, options) => {
      await new Promise<void>((resolve, reject) => {
        const timer = setTimeout(resolve, 200);
        options?.signal?.addEventListener("abort", () => {
          clearTimeout(timer);
          reject(new Error("aborted"));
        });
      });
      return new Response("never", { status: 200 });
    },
  });
  assert.equal(slow.via, "bundled");

  // With no bundled file, a failing fetch throws instead of silently serving
  // nothing.
  await assert.rejects(
    loadSiddhantaSource(jd, {
      baseUrl: "https://example.invalid",
      fetchImpl: async () => {
        throw new Error("unreachable");
      },
    }),
    /unreachable/,
  );

  // A server that answers wins over the bundled file.
  const stabB64 = readFileSync(
    new URL("./fixtures/siddhanta-2000.vtab.b64", import.meta.url),
    "utf8",
  );
  const served = await loadSiddhantaSource(jd, {
    baseUrl: "https://example.invalid",
    bundledCheb: bundled,
    fetchImpl: async () =>
      new Response(Buffer.from(stabB64.trim(), "base64"), { status: 200 }),
  });
  assert.equal(served.via, "server");
  const fromServer = served.source.positionsAt(jd);
  assert.ok(fromServer !== null);
  // The server slice and the fallback file agree to a few arcseconds.
  angleClose(fromServer.longitude[1], fallback.longitude[1], 0.005);
});
